def deploy(self, id_networkv4):
        """Deploy network in equipments and set column 'active = 1' in tables redeipv4

        :param id_networkv4: ID for NetworkIPv4

        :return: Equipments configuration output
        """
        equipments = Equipamento.objects.filter(rede__id=id_networkv4)

        for equipment in equipments:
            if not self.check_equipment_active(equipment.id):
                self.deploy_network_in_equipment(id_networkv4, equipment.id)

        self.update_network_active(id_networkv4)

        return self.get_network_configuration(id_networkv4)

